import{_ as t,o as a,c as o,a0 as n}from"./chunks/framework.Bmhw_dvp.js";const g=JSON.parse('{"title":"Admin Panel","description":"","frontmatter":{},"headers":[],"relativePath":"en/admin/admin-panel.md","filePath":"en/admin/admin-panel.md","lastUpdated":1788515531000}'),r={name:"en/admin/admin-panel.md"};function i(s,e,l,d,h,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="admin-panel" tabindex="-1">Admin Panel <a class="header-anchor" href="#admin-panel" aria-label="Permalink to &quot;Admin Panel&quot;">​</a></h1><p>The admin panel is ZViewer&#39;s administrative control center, where you can manage users, rooms, system settings, and version updates.</p><hr><h2 id="how-to-access-the-admin-panel" tabindex="-1">How to Access the Admin Panel <a class="header-anchor" href="#how-to-access-the-admin-panel" aria-label="Permalink to &quot;How to Access the Admin Panel&quot;">​</a></h2><p>There are two ways to access it:</p><ol><li><strong>Homepage button</strong>: On the homepage, find the &quot;<strong>Permissions</strong>&quot; button in the top navigation bar or on the page, and click to enter</li><li><strong>Direct URL</strong>: Enter <code>http://your-server-address/admin</code> in the browser address bar (e.g., <code>http://192.168.1.100:3000/admin</code>)</li></ol><blockquote><p>Only <strong>root</strong> and <strong>admin</strong> roles can see and access the admin panel. If you are a regular user or guest, the entry will not be displayed.</p></blockquote><h2 id="overview-of-the-four-tabs" tabindex="-1">Overview of the Four Tabs <a class="header-anchor" href="#overview-of-the-four-tabs" aria-label="Permalink to &quot;Overview of the Four Tabs&quot;">​</a></h2><p>Once you enter the admin panel, you will see four tabs at the top:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Description</th><th>Available Roles</th></tr></thead><tbody><tr><td><strong>User Management</strong></td><td>Manage user registrations, roles, and approvals</td><td>root only</td></tr><tr><td><strong>Room Management</strong></td><td>View and manage all rooms</td><td>root + admin</td></tr><tr><td><strong>Basic Settings</strong></td><td>Modify global system settings</td><td>root only</td></tr><tr><td><strong>Version Updates</strong></td><td>Check for and apply updates</td><td>root + admin</td></tr></tbody></table><hr><h2 id="user-management-tab-root-only" tabindex="-1">User Management Tab (root only) <a class="header-anchor" href="#user-management-tab-root-only" aria-label="Permalink to &quot;User Management Tab (root only)&quot;">​</a></h2><h3 id="registration-method-settings" tabindex="-1">Registration Method Settings <a class="header-anchor" href="#registration-method-settings" aria-label="Permalink to &quot;Registration Method Settings&quot;">​</a></h3><ol><li>In the &quot;Registration Method&quot; dropdown, select the desired mode: <ul><li><strong>Open Registration</strong>: Anyone who registers is activated immediately</li><li><strong>Approval Registration</strong>: Registration requires approval</li><li><strong>Registration Closed</strong>: The registration entry is disabled</li></ul></li><li>Click the &quot;<strong>Save</strong>&quot; button next to it; the setting takes effect immediately</li></ol><h3 id="user-list" tabindex="-1">User List <a class="header-anchor" href="#user-list" aria-label="Permalink to &quot;User List&quot;">​</a></h3><p>The page lists all registered users, displaying the following information:</p><ul><li>Username</li><li>Role (root / admin / user / guest)</li><li>Status (active / pending)</li><li>Registration time</li></ul><h3 id="approving-users" tabindex="-1">Approving Users <a class="header-anchor" href="#approving-users" aria-label="Permalink to &quot;Approving Users&quot;">​</a></h3><p>For users with a &quot;Pending&quot; status, an &quot;<strong>Approve</strong>&quot; button appears in the action column. Clicking it upgrades the user to a full user role.</p><h3 id="changing-roles" tabindex="-1">Changing Roles <a class="header-anchor" href="#changing-roles" aria-label="Permalink to &quot;Changing Roles&quot;">​</a></h3><p>Click &quot;<strong>Change Role</strong>&quot; in the user&#39;s action column to promote the user to admin or demote them to user/guest.</p><blockquote><p>Note: You cannot modify the root role&#39;s permissions, nor can you demote the last remaining root user.</p></blockquote><h3 id="deleting-users" tabindex="-1">Deleting Users <a class="header-anchor" href="#deleting-users" aria-label="Permalink to &quot;Deleting Users&quot;">​</a></h3><p>Click the &quot;<strong>Delete</strong>&quot; button to remove the user. This action cannot be undone, so proceed with caution.</p><hr><h2 id="room-management-tab" tabindex="-1">Room Management Tab <a class="header-anchor" href="#room-management-tab" aria-label="Permalink to &quot;Room Management Tab&quot;">​</a></h2><h3 id="room-list" tabindex="-1">Room List <a class="header-anchor" href="#room-list" aria-label="Permalink to &quot;Room List&quot;">​</a></h3><p>This tab lists <strong>all</strong> rooms currently on the server, including those created by other users. Each entry displays:</p><ul><li>Room name</li><li>Owner (creator)</li><li>Current online count</li><li>Viewing mode</li></ul><h3 id="view-switching" tabindex="-1">View Switching <a class="header-anchor" href="#view-switching" aria-label="Permalink to &quot;View Switching&quot;">​</a></h3><p>Two viewing modes are supported:</p><ul><li><strong>List View</strong>: Displayed as a table with more detailed information</li><li><strong>Card View</strong>: Displayed as cards for a more intuitive look</li></ul><p>Click the toggle button in the top-right corner to switch.</p><h3 id="batch-operations" tabindex="-1">Batch Operations <a class="header-anchor" href="#batch-operations" aria-label="Permalink to &quot;Batch Operations&quot;">​</a></h3><p>Select the checkboxes on the left of multiple rooms, then:</p><ul><li><strong>Batch Delete</strong>: Delete the selected rooms</li><li><strong>Delete All</strong>: Clear all rooms on the server (root only)</li><li><strong>Clean Unused Rooms</strong>: Automatically delete rooms with no viewers</li><li><strong>Refresh</strong>: Reload the room list to get the latest data</li></ul><blockquote><p>Deleting a room will disconnect all viewers in that room.</p></blockquote><hr><h2 id="basic-settings-tab-root-only" tabindex="-1">Basic Settings Tab (root only) <a class="header-anchor" href="#basic-settings-tab-root-only" aria-label="Permalink to &quot;Basic Settings Tab (root only)&quot;">​</a></h2><h3 id="auto-cleanup" tabindex="-1">Auto Cleanup <a class="header-anchor" href="#auto-cleanup" aria-label="Permalink to &quot;Auto Cleanup&quot;">​</a></h3><p>When enabled, the system automatically deletes rooms that have been unoccupied for a long time:</p><ul><li><strong>Auto Cleanup Toggle</strong>: Enable/disable this feature</li><li><strong>Cleanup Time</strong>: Set the number of hours after which an empty room is automatically deleted (e.g., 24 hours)</li></ul><h3 id="room-creation-permission" tabindex="-1">Room Creation Permission <a class="header-anchor" href="#room-creation-permission" aria-label="Permalink to &quot;Room Creation Permission&quot;">​</a></h3><p>Choose who can create rooms:</p><ul><li><strong>Admin Only</strong>: Only root and admin can create rooms</li><li><strong>All Users</strong>: User role can also create rooms</li></ul><h3 id="beta-feature-toggles" tabindex="-1">Beta Feature Toggles <a class="header-anchor" href="#beta-feature-toggles" aria-label="Permalink to &quot;Beta Feature Toggles&quot;">​</a></h3><p>You can enable or disable the following experimental features:</p><ul><li><strong>Kazumi Anime Source</strong>: Kazumi anime data source</li><li><strong>AniSubs Anime Source</strong>: AniSubs anime data source</li><li><strong>Bilibili Download</strong>: Bilibili video download feature</li></ul><p>Enabling beta features may affect system stability; use them as needed.</p><h3 id="browser-side-playback-engine-playsvideo" tabindex="-1">Browser-Side Playback Engine (playsvideo) <a class="header-anchor" href="#browser-side-playback-engine-playsvideo" aria-label="Permalink to &quot;Browser-Side Playback Engine (playsvideo)&quot;">​</a></h3><blockquote><p><strong>Note for older versions</strong>: the old &quot;Allow browser-side audio transcode (ffmpeg.wasm)&quot; global toggle, the &quot;wasm engine download source&quot; setting, and the &quot;Enable FFmpeg WASM engine&quot; checkbox when adding a movie have all been removed — no configuration is needed anymore.</p></blockquote><p>Browser-side container remuxing and audio transcoding are now handled <strong>fully automatically by the playsvideo engine</strong>, with no admin-panel toggles:</p><ul><li>Containers the browser cannot play directly — <strong>MKV / AVI / TS / WMV</strong> — are automatically remuxed to fMP4 in the browser during playback.</li><li>Browser-incompatible audio tracks — <strong>DTS / AC3 / EAC3</strong> — are transcoded to AAC in real time in the browser; the transcode core ships with the frontend assets.</li><li>No admin-panel configuration is required, and there is no longer any engine checkbox when adding a movie.</li></ul><h3 id="kazumi-rule-source-configuration" tabindex="-1">Kazumi Rule Source Configuration <a class="header-anchor" href="#kazumi-rule-source-configuration" aria-label="Permalink to &quot;Kazumi Rule Source Configuration&quot;">​</a></h3><p>If you use the Kazumi data source, you can configure the rule source URL here. Modifying this will clear the anime source cache and re-fetch data.</p><hr><h2 id="version-updates-tab" tabindex="-1">Version Updates Tab <a class="header-anchor" href="#version-updates-tab" aria-label="Permalink to &quot;Version Updates Tab&quot;">​</a></h2><h3 id="check-for-updates" tabindex="-1">Check for Updates <a class="header-anchor" href="#check-for-updates" aria-label="Permalink to &quot;Check for Updates&quot;">​</a></h3><p>Click the &quot;<strong>Check for Updates</strong>&quot; button, and the system will automatically query GitHub for new versions. If a new version is available, the version number and update details will be displayed.</p><h3 id="one-click-update" tabindex="-1">One-Click Update <a class="header-anchor" href="#one-click-update" aria-label="Permalink to &quot;One-Click Update&quot;">​</a></h3><p>Click the &quot;<strong>One-Click Update</strong>&quot; button, and the system will automatically download and apply the latest version. During the update process, the server will restart briefly, and users currently watching may be disconnected.</p><h3 id="manual-update-package-import" tabindex="-1">Manual Update Package Import <a class="header-anchor" href="#manual-update-package-import" aria-label="Permalink to &quot;Manual Update Package Import&quot;">​</a></h3><p>If the server cannot directly access GitHub (e.g., in an internal network environment), you can:</p><ol><li>Download the update package (<code>.zip</code> or <code>.tar.gz</code> format, up to 500MB) on another computer</li><li>Click &quot;<strong>Choose File</strong>&quot; on this page</li><li>Select the downloaded update package</li><li>Click &quot;<strong>Upload and Apply</strong>&quot;</li></ol><h3 id="receive-pre-release-versions" tabindex="-1">Receive Pre-release Versions <a class="header-anchor" href="#receive-pre-release-versions" aria-label="Permalink to &quot;Receive Pre-release Versions&quot;">​</a></h3><p>When this option is enabled, checking for updates will also show pre-release versions. Pre-release versions contain the latest features but may not be stable; it is recommended to use them only in test environments.</p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="cannot-see-the-admin-panel-entry" tabindex="-1">Cannot see the admin panel entry <a class="header-anchor" href="#cannot-see-the-admin-panel-entry" aria-label="Permalink to &quot;Cannot see the admin panel entry&quot;">​</a></h3><p>Possible reasons:</p><ol><li>The currently logged-in account is not a <strong>root</strong> or <strong>admin</strong> role</li><li>You are not logged in, or your session has expired</li><li>The page has not been refreshed -- try refreshing the homepage or directly accessing the <code>/admin</code> path</li></ol><h3 id="buttons-are-grayed-out-and-cannot-be-clicked" tabindex="-1">Buttons are grayed out and cannot be clicked <a class="header-anchor" href="#buttons-are-grayed-out-and-cannot-be-clicked" aria-label="Permalink to &quot;Buttons are grayed out and cannot be clicked&quot;">​</a></h3><ul><li>Certain operations (such as approving users, changing roles) are <strong>root only</strong></li><li>If you are an admin, seeing grayed-out buttons is normal because these features are not available to you</li></ul><h3 id="what-to-do-if-the-update-fails" tabindex="-1">What to do if the update fails <a class="header-anchor" href="#what-to-do-if-the-update-fails" aria-label="Permalink to &quot;What to do if the update fails&quot;">​</a></h3><ol><li>Check whether the server can access GitHub (whether <code>github.com</code> is reachable)</li><li>If network access is restricted, use the &quot;Manual Update Package Import&quot; method</li><li>Check the server logs for more detailed error information</li><li>If one-click update repeatedly fails, try downloading the update package manually and uploading it</li></ol>',75)])])}const m=t(r,[["render",i]]);export{g as __pageData,m as default};
